<?php
namespace App\Http\Controllers;
use App\Models\{DiscountCode,Product,ProductVariant};use App\Services\CheckoutDiscounts;use Illuminate\Http\Request;use Illuminate\Validation\Rule;use Illuminate\Validation\ValidationException;use Inertia\Inertia;
class DiscountCodeController extends Controller {
private function access(Request $r):void{abort_unless($r->user()?->hasPermission('discounts.manage'),403);}
public function index(Request $r,string $type){$this->access($r);return Inertia::render('DiscountCodes',['type'=>$type,'records'=>DiscountCode::where('type',$type)->latest()->get()]);}
public function form(Request $r,?DiscountCode $discount=null,string $type='coupon'){$this->access($r);if($discount)abort_unless($discount->type===$type,404);return Inertia::render('DiscountCodeForm',['type'=>$type,'record'=>$discount]);}
public function save(Request $r,?DiscountCode $discount=null,string $type='coupon'){$this->access($r);if($discount)abort_unless($discount->type===$type,404);$r->merge(['code'=>strtoupper(trim($r->input('code','')))]);$data=$r->validate(['name'=>'required|string|max:150','code'=>['required','string','max:60','regex:/^[A-Z0-9_-]+$/',Rule::unique('discount_codes')->where('type',$type)->ignore($discount?->id)],'amount'=>'required|numeric|min:0.01|max:99999999.99','status'=>'required|boolean']);if($discount)$discount->update($data);else DiscountCode::create(['type'=>$type,...$data]);return redirect($type==='coupon'?'/admin/coupons':'/admin/gift-cards')->with('success','Discount code saved.');}
public function destroy(Request $r,DiscountCode $discount,string $type){$this->access($r);abort_unless($discount->type===$type,404);$discount->delete();return back()->with('success','Discount code removed.');}
public function preview(Request $r,CheckoutDiscounts $discounts){$data=$r->validate(['coupon_code'=>'nullable|string|max:60','gift_card_code'=>'nullable|string|max:60','items'=>'required|array|min:1|max:30','items.*.product_id'=>'required|integer','items.*.variant_id'=>'nullable|integer','items.*.quantity'=>'required|integer|min:1|max:100']);$cents=0;$seen=[];foreach($data['items'] as $i=>$line){$key=$line['product_id'].'-'.($line['variant_id']??'default');if(isset($seen[$key]))throw ValidationException::withMessages(['items'=>'Duplicate product options.']);$seen[$key]=true;$p=Product::find($line['product_id']);if(!$p||!$p->status)throw ValidationException::withMessages(['items'=>'A product is unavailable.']);$v=!empty($line['variant_id'])?ProductVariant::find($line['variant_id']):null;if(($line['variant_id']??null)&&(!$v||$v->product_id!==$p->id)||($p->variants()->exists()&&!$v))throw ValidationException::withMessages(['items'=>'Choose valid product options.']);$price=$v?(float)$v->price:(float)($p->sale_price>0?$p->sale_price:$p->regular_price);$cents+=(int)round($price*100)*$line['quantity'];}return response()->json($discounts->calculate($cents/100,$data['coupon_code']??null,$data['gift_card_code']??null));}
}
